insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 1, 'Why can proppant not be carried from the very first minute of a treatment?', '["The blender cannot reach its final concentration quickly enough.", "The carrier fluid has not yet crosslinked at the start of a job, so it lacks the viscosity needed to hold grains in suspension.", "A grain meeting an aperture only a few diameters wide bridges at the perforations and screens the job out.", "Proppant pumped early would settle to the base of the fracture before closure."]'::jsonb, 2, 'A bridge at the perforations is the worst place for one, because the fracture then closes on clean fluid with a plug at its mouth.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 2, 'At the published conditions of this treatment, what share of the pump time is spent on clean pad fluid?', '["About 0.7052381992848291 of the pump time, or 2782.3263142525348 s of clean fluid ahead of the slurry.", "About 0.1728566723633056 of the pump time, the fluid efficiency.", "About 0.8271433276366944 of the pump time, since the share spent on pad must equal the share of fluid lost to leakoff.", "About 0.5 of the pump time, with the ramp taking the other half of the job."]'::jsonb, 0, 'At the injection rate of 0.053 m3/s that pad is 147.46329465538435 m3, and the 1162.9028538130178 s left carries every kilogram of proppant.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 3, 'Most of the pad never comes back to the wellbore. Where does it go during pumping?', '["It is displaced ahead of the slurry and stored at the fracture tip.", "It is broken down by the breaker schedule into a thin fluid that flows back to surface over the first days of production.", "It stays in the fracture as the 36.143836842230584 m3 measured at the end of pumping.", "It leaks through the fracture faces into the formation, which takes 172.95330906524367 m3 of the injection."]'::jsonb, 3, 'Calling that volume wasted misreads the job, since it is the price paid for an aperture wide enough to be worth filling.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 4, 'Nolte''s schedule is built around a single exponent. How does that exponent follow from the fluid efficiency?', '["One minus the efficiency, with no further correction applied.", "One minus the efficiency, divided by one plus the efficiency, which gives 0.7052381992848291 on this case.", "The square root of one minus the efficiency, which keeps the exponent between zero and one across the whole range.", "The efficiency divided by one plus the efficiency, which stays small when leakoff is heavy."]'::jsonb, 1, 'The engine calls the quantity eps, and the material balance efficiency of 0.1728566723633056 is its only argument.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 5, 'Where else does that exponent appear once it has fixed the length of the pad stage?', '["It is the power to which dimensionless time is raised in the concentration ramp of the slurry stage.", "It scales the leakoff coefficient used in the material balance.", "It becomes the exponent in the width equation that turns net pressure into the average fracture width during pumping.", "It multiplies the end of job concentration to give the first step of the staircase."]'::jsonb, 0, 'Two different jobs are done by one number, which is why an error in the efficiency corrupts the pad and the ramp together.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 6, 'What design condition does the power law concentration ramp satisfy?', '["The blender holds a constant concentration throughout the slurry stage.", "The concentration at the wellbore stays below the value at which the perforations would bridge at any point of the job.", "Every parcel of slurry arrives at the same concentration at the end of the job, so the pack is not graded.", "The slurry reaches the tip before the pad has finished leaking off into the formation."]'::jsonb, 2, 'Without that condition the early parcels, which travel furthest and leak most, would arrive far richer than the late ones.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 7, 'How does the Nolte exponent differ from the Nolte leakoff factor met in the tier below?', '["They are the same quantity under two different names.", "The exponent runs from 0 at perfect efficiency towards 1 as efficiency falls, over a far wider span.", "The leakoff factor corrects the concentration ramp, while the exponent corrects the leakoff area for fracture growth.", "The exponent climbs towards 1.5589231771218184 as the efficiency falls to 0.05."]'::jsonb, 1, 'The leakoff factor moves only between 1.3333333333333333 and 1.5589231771218184, so the two are easy to tell apart once compared.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 8, 'The slurry concentration follows a power law in dimensionless time. What shape does that curve take here?', '["A straight line from zero up to the end of job concentration.", "Convex, staying low through most of the slurry stage and then rising steeply at the end, because the exponent is below 1.", "Concave over the first half of the ramp and convex over the second half of it.", "Concave, climbing quickly at first and flattening as it nears 800 kg/m3, because the exponent is below 1."]'::jsonb, 3, 'The curve starts from zero, so the very first slurry stage is lean and no stage ever reaches the full end of job value.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 9, 'Why does the engine evaluate that power law at the midpoint of each of the eight stages?', '["Midpoint sampling keeps the staircase from running systematically rich or lean against the curve it replaces.", "It is the only point at which the blender can change stage.", "The midpoint is where the slurry pumped during a stage will finally come to rest inside the fracture.", "It guarantees that the final stage is pumped at the full end of job concentration."]'::jsonb, 0, 'Each stage carries the same slurry volume over the same length of time, so only the concentration changes between them.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 10, 'What accounts for the division by one plus the exponent in the placed mass expression?', '["It converts the slurry volume into a clean fluid volume.", "It corrects the injection rate for the share of the slurry that leaks off through the fracture faces while pumping.", "It is the average value of dimensionless time raised to the exponent, taken across the slurry stage.", "It accounts for the eight stages the blender holds during the ramp."]'::jsonb, 2, 'That single division is the whole of the ramp''s effect on the mass, which comes to 28915.069473784468 kg here.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 11, 'A designer takes one minus the efficiency as the pad fraction. In which direction does that err?', '["It understates the pad whenever the efficiency is below one half.", "It always overstates the pad, because dividing by one plus a positive efficiency makes the answer smaller.", "It errs either way, depending on whether the efficiency sits above or below the value of the exponent itself.", "It overstates the pad on low leakoff jobs and understates it on high leakoff jobs."]'::jsonb, 1, 'The error therefore never leaves too little pad, so a screenout will not warn the designer that the wrong form is in use.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 12, 'What does the naive form leave for the ramp when the efficiency is 0.1728566723633056?', '["Only the efficiency itself, 0.1728566723633056 of the pump time, and well under two thirds of the mass.", "The full 1162.9028538130178 s that the correct schedule allows.", "About 0.8271433276366944 of the pump time, since the naive form makes the pad and the ramp swap their roles.", "Roughly half the pump time, since the two forms differ by 0.12190512835186529."]'::jsonb, 0, 'One minus one minus the efficiency is the efficiency, so the arithmetic collapses neatly and the loss of mass is exact.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 13, 'Across the range of efficiencies, where does the gap between the two pad forms reach its widest?', '["At perfect efficiency, where both forms give no pad at all.", "At very poor efficiency, near an efficiency of 0.01460645625334061, where the pad approaches the whole of the job.", "The gap grows steadily as efficiency falls and is widest at the lowest efficiency.", "In the middle of the range, near an efficiency of 0.39582605426929196, where the gap is 0.17133065276968784."]'::jsonb, 3, 'Both ends are pinned, one because there is no pad to argue about and the other because the pad is already almost everything.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 14, 'A job pumped with too much pad returns a treating record that looks entirely normal. What went wrong downhole?', '["The perforations bridged early and the pumps came off.", "The extra clean fluid raised the net pressure enough to grow height into the bounding layers above and below the pay.", "The fracture was driven beyond the reach of the proppant, so the far length closed unpropped and the pack is thin.", "The proppant settled into a bank at the base of the fracture and left the upper height empty."]'::jsonb, 2, 'Nothing screens out and nothing alarms, so the only symptom is a well that quietly underperforms its forecast.'),
  ('stimulation', 'advanced', 'module', 'm01-the-pad-and-the-ramp', 15, 'Why might an engineer working only very high leakoff treatments use the naive form for years unpunished?', '["Such jobs place so little proppant that the pad hardly matters.", "At low efficiency both forms give almost all pad, so the disagreement between them has very little room left.", "Very high leakoff drives the efficiency towards 1, where the two forms agree exactly and the gap closes to nothing.", "The naive form happens to be correct whenever the leakoff coefficient exceeds 0.0002."]'::jsonb, 1, 'At a leakoff coefficient of 0.0004 the gap is only 0.014185901933060352, which hides inside the ordinary scatter of a job.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 1, 'Which quantities together set the mass of proppant a treatment finally places?', '["The fracture half-length, the height and the propped width.", "The end of job concentration, the injection rate and the ramp time, divided by one plus the exponent.", "The injected volume, the fluid efficiency and the closure stress acting on the pack once the pumps have come off.", "The pad volume and the leakoff coefficient, since the pad occupies most of the job."]'::jsonb, 1, 'Only three levers move the mass, and the ramp time is not set directly because it is the pump time less the pad.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 2, 'What does the 147.46329465538435 m3 of clean pad contribute to the mass that is placed?', '["About a fifth of the mass, carried as fines within the clean fluid.", "It supplies the proppant that reaches the tip, which is the part of the pack the later slurry stages cannot reach.", "It contributes in proportion to its volume, since mass scales with the volume injected.", "Nothing directly, since it carries no solid and enters the answer only through the ramp time it took away."]'::jsonb, 3, 'The carrier fluid contributes nothing either, whether it leaked away or stayed as the 36.143836842230584 m3 left in the fracture.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 3, 'Why is the placed mass the one property of a treatment that outlasts the job itself?', '["Width, length and treating pressure belonged to a fracture that closes, whereas the pack is permanent.", "It is the only quantity measured directly at surface.", "A closure stress of 38131950.890444934 Pa compacts the pack until its mass is the only quantity production leaves unchanged.", "It is the only input the engine refuses to accept as a range rather than as a value."]'::jsonb, 0, 'Every step downstream, from areal concentration to conductivity, inherits whatever error was made in the mass.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 4, 'How is areal concentration obtained from the mass a job has placed?', '["Divide the mass by the propped width and the pack porosity.", "Divide the mass by four times the half-length times the height, since fluid leaks through both walls of both wings.", "Divide the mass by twice the half-length times the height, which gives 3.212785497087163 kg/m2 here.", "Divide the mass by the half-length times the height, counting the fracture once."]'::jsonb, 2, 'The half-length is 150 m and the height 30 m on this case, so the plan area counts each of the two wings exactly once.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 5, 'The leakoff area and the area behind areal concentration differ by a factor of two. What explains it?', '["The leakoff area is quoted per wing and the pack area for both.", "Leakoff is computed over the created length while areal concentration is computed over the propped length, which is shorter.", "The leakoff area includes the tip region of the fracture, which carries no proppant at all.", "Fluid leaks through both walls of both wings, while the pack fills the single gap between those two walls."]'::jsonb, 3, 'Remembering what the answer is for settles it, since this area feeds a width that spans wall to wall rather than a coating on one face.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 6, 'What makes areal concentration the quantity a conductivity laboratory reports its results against?', '["It is the only pack property that does not depend on closure stress.", "A cell is loaded with a stated mass over a stated platen area, so that loading carries across to the well.", "The cell reports a width directly, and this is the only route from a measured width back to a mass for design.", "It removes any need to know the proppant grain density when two proppant families are compared."]'::jsonb, 1, 'Mass alone would depend on the size of the cell, and width alone would beg the question the test exists to answer.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 7, 'With a damage factor of 0.5 in force, what does the pack retain at the published closure stress?', '["The full catalogue value, since damage applies to the width.", "A retained permeability of 250 darcy, the catalogue value at 2 thousand psi held constant to higher stress.", "A retained permeability of 6.512770069532134e-11 m2, half of the laboratory value taken from the catalogue.", "A permeability that returns to the laboratory value once the well has cleaned up."]'::jsonb, 2, 'Applying the propped width to that permeability gives a conductivity of 9.84433461550515e-14 m3.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 8, 'Which density turns an areal concentration into a propped width?', '["The bulk density of the settled pack, being the grain density multiplied by one minus the pack porosity.", "The grain density of the ceramic proppant, taken as 3270 kg/m3.", "The slurry density at the end of the job, which combines the carrier fluid with the 800 kg/m3 of proppant in it.", "The grain density divided by one minus the pack porosity, which is larger than either of them."]'::jsonb, 0, 'The statement is physical, since spreading that mass over that area and letting it settle leaves a pack of exactly that thickness.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 9, 'How does a propped width of 0.0015115434001821517 m compare with the width that was actually pumped?', '["It is slightly larger, because the pack resists the closing walls.", "It is well under half of the average created width, which stood at 0.004015981871358954 m during pumping.", "It sits close to the maximum created width of 0.006391633661942177 m, since the pack holds the widest point open.", "It is about the same as the average created width, because the pack fills the whole aperture."]'::jsonb, 1, 'Any design showing a propped width near the created width should be checked for an arithmetic slip before it is believed.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 10, 'What occupied the difference between created and propped width while the pumps were still running?', '["Proppant that later crushed under the closure stress.", "Formation rock that spalled from the fracture faces during pumping and was carried out towards the tip by the slurry.", "Gas that came out of solution as the fracture pressure fell below the bubble point.", "Carrier fluid, held there by a net pressure of 2889735.9944400033 Pa that bleeds away once pumping stops."]'::jsonb, 3, 'That fluid either leaked off, flowed back, or stayed as unbroken gel in the pores of the pack, so the created width was spent rather than lost.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 11, 'A design divides its areal concentration by the grain density alone. What happens to the answer?', '["It understates the propped width by the factor one minus 0.35, and understates the conductivity with it.", "It overstates the width by about a third of the answer.", "It leaves the width unchanged, because the porosity cancels against the pack permeability when conductivity is formed.", "It understates the width only where the pack porosity differs from the catalogue value."]'::jsonb, 0, 'An error of that size is larger than most of the uncertainties argued over at a design meeting.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 12, 'Why can such a porosity omission survive years of design review without anyone catching it?', '["It affects only proppants whose porosity is above 0.35.", "It cancels within the dimensionless conductivity, so the pseudo-skin and the productivity index come out unaffected.", "It is a pessimistic error, and nobody complains about a well that beat the forecast it was given.", "It is smaller than the rounding the engine applies to the propped width."]'::jsonb, 2, 'Errors that flatter the reservoir get argued over, while errors that flatter the engineer''s caution rarely do.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 13, 'Pack permeability already describes a pack that has voids. Why does the width still need a porosity?', '["It is not needed, and the engine carries it only for reporting.", "Permeability describes how fluid moves through the voids, while porosity sets how thick the grains stand.", "The catalogue permeabilities of 250, 180, 120 and 70 darcy are all quoted at one reference porosity that must be corrected.", "Porosity corrects the permeability for the closure stress bearing on the pack."]'::jsonb, 1, 'One quantity is about flow and the other about geometry, and multiplying them together is precisely what conductivity is.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 14, 'Suppose the damage factor is halved while every other input is held fixed. What follows?', '["The conductivity, the dimensionless conductivity and the pseudo-skin all halve along with the factor.", "Nothing changes, since the factor cancels in the pseudo-skin.", "The propped width halves as well, because the damage factor stands for grains embedding into the fracture walls.", "Only the retained permeability changes, and the conductivity is left unaffected."]'::jsonb, 0, 'Because it carries straight through, the factor should be quoted beside the answer rather than buried in the inputs.'),
  ('stimulation', 'advanced', 'module', 'm02-from-slurry-to-pack', 15, 'Why is the damage factor taken as a stated input instead of being computed from the design?', '["It is measured directly in the conductivity cell before a job.", "It is derived from the closure stress by the same log-linear interpolation that supplies the pack permeability.", "Residue, fines and embedment turn on breakers, formation and rock strength that a frac design does not know.", "It is fixed at 0.5 for every treatment, so there is nothing left to compute."]'::jsonb, 2, 'The engine simply requires the value to lie above 0 and no higher than 1, and a factor of 1 claims the well reproduces the laboratory.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 1, 'Which two quantities does the engine multiply together to obtain the fracture conductivity kfw?', '["The formation permeability and the fracture half-length.", "The areal proppant concentration and the pack porosity, which together fix how much of the channel is open to flow.", "The retained pack permeability and the propped width, which is why the result carries the dimensions of a volume.", "The slurry concentration and the gross fracture height summed over both wings."]'::jsonb, 2, 'A permeability in square metres times a width in metres is a volume, so the engine reports kfw in cubic metres.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 2, 'Halving the pack permeability while holding conductivity fixed demands what change in propped width?', '["The width must double, because the two terms enter conductivity as a product and trade against each other one for one.", "The width must fall by half to keep the pack in balance.", "The width is unaffected, since conductivity is governed by the formation permeability rather than by the pack itself.", "The width must rise by roughly a quarter once the pack porosity is allowed for."]'::jsonb, 0, 'That single trade is why proppant grade and proppant volume are one design decision rather than two independent ones.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 3, 'In the dimensionless conductivity ratio, what does the denominator measure?', '["The pressure drop from the fracture tip back to the well.", "The ability of the reservoir to deliver fluid into the fracture across the face of both wings.", "The capacity of the pack to carry fluid along the channel from the tip towards the wellbore, per unit of width.", "The total volume of proppant placed during the treatment."]'::jsonb, 1, 'Half-length sits in that denominator, so extending the fracture without adding pack drives the ratio down.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 4, 'A published dimensionless conductivity of 0.6649847808507611 read against an optimum of 1.6 tells the designer what?', '["The job is starved of length and needs a longer fracture.", "The job already sits above the optimum, so the proppant budget could be trimmed without any measurable loss of deliverability.", "The job lies outside the correlation band and the result carries a warning.", "The job is starved of conductivity, so more pack rather than more half-length is the purchase that will help."]'::jsonb, 3, 'Another fifty metres of half-length with the same pack would push the ratio further below 1.6 rather than towards it.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 5, 'The proppant catalogue carried by the engine is tabulated against which independent variable?', '["Areal proppant loading in kilograms per square metre.", "Closure stress expressed in thousands of psi, with a nominal pack permeability in darcies read against each row.", "Propped width in millimetres, so that the table can be entered directly once the placed mass has been spread over the faces.", "Proppant mesh size, with one row for each sieve cut in the catalogue."]'::jsonb, 1, 'Areal loading feeds the width term instead, and it never enters the permeability lookup at any point.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 6, 'How does the engine treat a closure stress that falls between two tabulated catalogue rows?', '["It interpolates log-linearly between the two bracketing permeability values rather than snapping to the nearer row.", "It averages the two rows arithmetically and uses that mean.", "It fits a power law through every row in the table and evaluates that fit, so the answer is never a tabulated value.", "It rounds down to the lower closure row so that the estimate stays conservative."]'::jsonb, 0, 'The published closure of 5.530572 kpsi sits between the 4 and 6 kpsi rows and lands on about 131.98 darcy.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 7, 'What happens when a closure stress of 10 kpsi is handed to the catalogue lookup?', '["The engine throws, because the value lies outside the table.", "The trend of the last two rows is projected forward, so the returned permeability keeps falling past the table edge.", "The lookup is clamped to the 8 kpsi edge value and a clamped flag is raised instead of extrapolating the curve.", "The permeability is set to zero on the grounds that the pack is fully crushed."]'::jsonb, 2, 'Those rows are approximate planning data, and a real design is governed by vendor cells measured to API RP 19D.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 8, 'Across the tabulated closure range for 20 by 40 ISP ceramic, how does pack permeability move?', '["It falls from 250 darcy to 180 darcy across the table.", "It holds near 250 darcy until the last row, because a ceramic proppant is manufactured to resist crushing entirely.", "It rises with closure as the pack compacts and the grains lock together.", "It falls from 250 darcy at 2 kpsi to 70 darcy at 8 kpsi, with nothing but the load on the grains changed."]'::jsonb, 3, 'The loss comes from grain crushing and rearrangement, and a ceramic is bought to push that collapse further down the stress axis.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 9, 'Which mechanism explains the collapse in pack permeability as the rock leans harder on the proppant?', '["Point contacts between grains fail, fines are generated, and those fines migrate into the pore throats of the pack.", "The grains dissolve slowly in the produced formation water.", "Unbroken polymer from the carrier fluid is squeezed deeper into the pack, which is the separate loss counted by the damage factor.", "The propped width falls because the fracture faces embed into the pack."]'::jsonb, 0, 'Nothing about the grains themselves changes between the shallowest and the deepest tabulated closure, only the load.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 10, 'What does the damage factor of 0.5 used by the published job stand for?', '["The load the rock places on the grains once the fracture closes.", "The proportion of the placed proppant mass that never reaches the fracture because it screens out near the perforations.", "Unbroken polymer, filter cake residue, trapped fluid and fines blocking part of the pore space of the pack.", "The share of the created fracture height that ends up propped rather than closed."]'::jsonb, 2, 'Closure loss is already inside the catalogue value, so the damage factor is strictly the second and separate bite.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 11, 'Which permeability does the engine carry into the conductivity product once damage has been applied?', '["The catalogue value read at the published closure stress.", "The retained value, about 65.990641 darcy, rather than the roughly 131.98 darcy read from the table at that closure.", "The undamaged laboratory value of 250 darcy, since the correlation behind conductivity was fitted to clean packs.", "The formation permeability of 1 mD, because the pack cannot flow better than the rock feeding it."]'::jsonb, 1, 'The dimensionless conductivity, the pseudo-skin and the effective radius all descend from the retained figure.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 12, 'Which damage factor values will the engine accept without throwing?', '["Any value from zero to one inclusive, zero meaning a dead pack.", "Any positive value at all, since a factor above one simply represents a pack improved by an effective breaker system.", "Only values strictly below one, because no field pack is ever undamaged.", "Any value greater than zero and up to and including one, where one describes an undamaged laboratory pack."]'::jsonb, 3, 'A multiplier above one would claim the treatment improved the pack, which the engine treats as an input error.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 13, 'Along the fixed proppant sweep, how does each further step up in dimensionless conductivity pay back?', '["The gain shrinks steadily and then reverses, so the highest ratios read a worse pseudo-skin than the middle rows.", "The gain grows steadily, since a more conductive pack always drains more.", "The gain stays constant, because the pseudo-skin depends on the logarithm of the length ratio and on nothing else.", "The gain shrinks only once the correlation range warning has been tripped."]'::jsonb, 0, 'A 30 m fracture at a ratio of 16.62461952126903 is beautifully conductive and yet drains almost nothing.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 14, 'Searching that sweep for the very best pseudo-skin lands on which half-length and ratio?', '["150 m at 0.6649847808507611, the published design point.", "30 m at 16.62461952126903, since the shortest fracture in the sweep carries much the most conductive pack of any row.", "About 95.62290278496067 m at a dimensionless conductivity of 1.6363280590574483, close to the carried constant.", "440 m at 0.07728387174143661, where the fracture contacts the most reservoir face."]'::jsonb, 2, 'Agreement within a few per cent is exactly where the 1.6 optimum the engine carries as a constant comes from.'),
  ('stimulation', 'advanced', 'module', 'm03-conductivity', 15, 'Why does widening the channel further stop buying pseudo-skin once the pack is already generous?', '["The correlation is clamped once the ratio passes the top of its band.", "The pressure drop along the fracture that is being removed was never large, so the reservoir sets the limit.", "The extra conductivity is offset by the damage factor, which the engine reapplies at every step of the sweep as width grows.", "The half-length drops out of the pseudo-skin expression above a ratio of 1.6."]'::jsonb, 1, 'Meanwhile every step up the conductivity column was paid for in length, and length sets how much rock face is exposed.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 1, 'Why must a fracture be expressed as a skin before an inflow performance relationship can use it?', '["Skin is the only quantity a nodal analysis package will accept.", "An equation written for radial flow into a cylindrical hole carries no term at all for a plane.", "The fracture changes the permeability of the rock near the wellbore, and skin is defined as exactly that kind of alteration.", "The correlation cannot be evaluated until any damage skin has first been removed."]'::jsonb, 1, 'It is called a pseudo-skin because no permeability near the well has changed, only the geometry of the flow path.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 2, 'What sets a fracture pseudo-skin apart from an ordinary damage skin?', '["It is measured from a build-up rather than from a flow test.", "It stays positive but small, since a pack of finite conductivity still restricts flow more than the intact formation.", "It applies only in carbonates, where acid has already dissolved part of the matrix.", "It comes out negative because the fracture adds deliverability, and no rock permeability has actually been altered."]'::jsonb, 3, 'A perfectly cleaned up damaged sandstone can only reach zero, whereas the published carbonate acid job reaches -1.287406553.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 3, 'What did Cinco-Ley and Samaniego actually solve and then publish?', '["The coupled problem of flow along a finite-conductivity vertical fracture and flow from the reservoir into it, numerically.", "An analytical solution for an infinitely conductive fracture.", "A laboratory programme of conductivity cell measurements on ceramic packs, later fitted with a rational function by others.", "A material balance for the proppant placed across both wings."]'::jsonb, 0, 'Their chart collapses onto a single curve because only two dimensionless groups matter to the answer.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 4, 'Their published chart plots which quantity on its vertical axis?', '["The propped width divided by the fracture half-length.", "The effective wellbore radius divided by the drainage radius, on logarithmic axes covering the full valid band.", "The pseudo-skin added to the logarithm of the length ratio, which is what makes the whole family collapse.", "The pack permeability against closure stress on the proppant."]'::jsonb, 2, 'The engine carries a rational function fitted to that curve rather than the chart itself.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 5, 'Besides the fracture geometry, which flow regime does the fitted correlation describe?', '["The bilinear regime inside the pack and across the face.", "The stabilised radial regime, and not the early transient period that follows immediately after a treatment.", "The linear regime perpendicular into the fracture face, which is what fracture diagnostics read in the first hours.", "Pseudo-steady depletion within a closed drainage boundary of 300 m."]'::jsonb, 1, 'Everything derived from the fit inherits exactly that scope and nothing wider, the effective radius included.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 6, 'What is assumed about the shape and symmetry of the fracture itself?', '["That it is horizontal and centred on the top of the perforations.", "That it is elliptical in plan with the width tapering to zero at the tip, as the material balance in this course assumes.", "That it grows only in the wing facing the lower closure stress.", "That it is vertical, planar and of uniform width, with two wings of equal half-length about the well."]'::jsonb, 3, 'Neither of those assumptions is negotiable, so an asymmetric or highly contained fracture sits outside the fit.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 7, 'A dimensionless conductivity outside 0.1 to 1000 is handled by the engine in what way?', '["It is still computed, and a warning is attached naming the offending ratio together with the stated valid range.", "The input is refused and the routine throws before computing.", "The ratio is clamped to the nearer limit of the band and the pseudo-skin is returned at that limit, flagged as clamped.", "The 1.6 optimum is substituted so that the answer stays in range."]'::jsonb, 0, 'Below 0.1 the correlation shape leaves the numerical solution, and above 1000 the fracture is effectively infinite in conductivity.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 8, 'Which inputs make the pseudo-skin routine throw rather than merely warn?', '["Any dimensionless conductivity falling outside 0.1 to 1000.", "A damage factor above one, a closure stress beyond the top row of the proppant table, or a pad fraction over unity.", "A conductivity or a formation permeability that is not positive, or a half-length not strictly above the hole radius.", "A drainage radius smaller than the effective wellbore radius returned."]'::jsonb, 2, 'That length guard exists because a logarithm of a ratio at or below one would make a stub fracture look beneficial.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 9, 'How is the f function evaluated inside the engine?', '["By interpolating a stored table of readings from the chart.", "As a quadratic over a cubic, with no iteration, no table lookup and no second branch anywhere in the routine.", "By Newton iteration on the pseudo-skin until the assumed and computed dimensionless conductivities agree to tolerance.", "By a power law fitted separately above and below a ratio of 1.6."]'::jsonb, 1, 'The numerator coefficients are 1.65, -0.328 and 0.116, and the denominator runs 1, 0.18, 0.064 and 0.005.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 10, 'What single argument does that rational function take?', '["The natural logarithm of the dimensionless conductivity, written as u wherever the expression appears.", "The ratio of half-length to the drilled wellbore radius.", "The conductivity in millidarcy metres, divided through by the formation permeability and by the fracture half-length.", "The closure stress in thousands of psi taken from the proppant table."]'::jsonb, 0, 'A logarithm is used because the ratio spans four decades and the skin responds to order of magnitude, not to value.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 11, 'Evaluating the expression at u equal to zero returns what value, and at which ratio?', '["It returns zero, at a dimensionless conductivity of 1.6.", "It returns 1.9246212796864688, the published figure, because the published job happens to sit at the point where u is zero.", "It returns 0.116, the coefficient on the squared term above the line.", "It returns 1.65, the numerator constant, at a dimensionless conductivity of one where the logarithm vanishes."]'::jsonb, 3, 'At high ratios the cubic in the denominator outruns the numerator and f falls towards zero, the infinite conductivity limit.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 12, 'Given a published f of 1.9246212796864688 and a pseudo-skin of -5.3116380662677045, what is the length term?', '["The logarithm of the length ratio is 3.386 across both wings.", "The logarithm of the length ratio is 1388.9, which is the plain ratio of half-length to hole radius before any logarithm.", "The logarithm of the length ratio is 7.236259345954173, from 150 m of half-length over a 0.108 m hole radius.", "The logarithm of the length ratio equals the pseudo-skin itself by definition."]'::jsonb, 2, 'More than three decades of e separate the drilled radius from the half-length, and every one is subtracted from the skin.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 13, 'At fixed proppant volume, lengthening the fracture moves the two terms of the pseudo-skin how?', '["The length logarithm rises and helps, while the falling ratio lifts f and takes part of that gain straight back.", "Both terms rise together, so the pseudo-skin always improves.", "The length logarithm is unchanged because it depends on the drilled radius, while f falls and improves the skin steadily.", "Both terms fall, so the pseudo-skin becomes less negative at once."]'::jsonb, 0, 'Balancing those two opposing moves is precisely what the unified optimum in the previous module is searching for.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 14, 'By what operation does the engine turn a pseudo-skin back into an equivalent radius?', '["The drainage radius is divided by the pseudo-skin as a fraction.", "The drilled radius is multiplied by the exponential of the negative pseudo-skin, giving 21.889652014700083 m here.", "The fracture half-length is added to the drilled radius, since the fracture doubles the contact area on each of its wings.", "The drilled radius is multiplied by the pseudo-skin taken as a positive number."]'::jsonb, 1, 'The skin sits inside an exponential, so each further unit of negative skin multiplies the effective radius again.'),
  ('stimulation', 'advanced', 'module', 'm04-the-fracture-as-a-skin', 15, 'Which conditions does the effective wellbore radius equivalence fail to describe?', '["Only pseudo-steady depletion late in the life of the well.", "None of them, since the equivalence is a statement about geometry and therefore holds in every flow regime alike.", "Early transient flow into the fracture face, the flowback period before cleanup, and any production of a second phase.", "Stabilised radial flow, which the fitted correlation never covered."]'::jsonb, 2, 'Diagnostics read the early data precisely because a large hole shows none of the bilinear behaviour a finite pack produces.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 1, 'The engine stores the unified design optimum as a named constant. What value does it hold, and over what band is its pseudo-skin correlation stated to apply?', '["CFD_OPTIMUM is 1.6, with a stated validity band running from 0.01 up to 100.", "CFD_OPTIMUM is 1.6, and the correlation is declared valid for dimensionless conductivities from 0.1 to 1000.", "CFD_OPTIMUM is 1.6363280590574483, and the correlation is declared valid for dimensionless conductivities from 0.1 to 1000.", "CFD_OPTIMUM is 1.6, and the correlation is stated to apply between 1 and 1000."]'::jsonb, 1, 'The band matters in practice: the 440 m row of the sweep falls under the floor, so its skin is printed but is off the correlation''s stated ground.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 2, 'What separates a constant you can rederive by an independent route from one you can only cite?', '["The rederived one is a result of the physics; the cited one is a convention worth only the trust placed in its source.", "Only a rederived constant may be quoted in a design review.", "The rederived constant is exact to sixteen figures, whereas a cited constant has always been rounded before it appears in a paper.", "The rederived constant holds in every formation, while a cited one is valid only for the case it was originally measured on."]'::jsonb, 0, 'Agreement to a couple of per cent counts as agreement for a design rule of this kind, and the optimum would still sit near 1.6 had nobody ever published it.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 3, 'The golden-section routine in the panel drives one quantity to its best value. Which quantity, and what does it deliberately not consult?', '["It maximises conductivity and never reads the half-length.", "It hunts for the half-length whose dimensionless conductivity sits closest to 1.6, so the constant is the target of the search itself.", "It drives the pseudo-skin as negative as it will go, and it never reads the published CFD_OPTIMUM constant.", "It maximises the propped width at fixed proppant volume, ignoring the pseudo-skin correlation altogether."]'::jsonb, 2, 'At each trial half-length the routine computes the width the pack can afford, then the conductivity that follows, then the skin from the correlation.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 4, 'Where does the continuous search come to rest, and how near is it to the number the engine already carries?', '["At 150 m, where the conductivity works out at 0.6649847808507611.", "At 120 m, where the conductivity of 1.0390387200793143 lies nearest to the published constant.", "At a half-length of 90 m and a conductivity of 1.8471799468076697, which is the best row the discrete nine point sweep contains.", "At 95.62290278496067 m half-length, conductivity 1.6363280590574483, a ratio of 1.0227050369109052 to the constant."]'::jsonb, 3, 'The pseudo-skin there is -5.4132436175894565, better than the value at either grid row the searched half-length falls between.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 5, 'Discrete sweep and continuous search return different answers. Why does the grid land where it lands?', '["Ninety metres was one of the nine half-lengths the sweep happened to include, so a grid returns its best row.", "The grid uses a coarser pseudo-skin correlation than the search does.", "The grid evaluates skin at fixed conductivity rather than at fixed proppant volume, so none of its rows are comparable.", "The grid halts as soon as the pseudo-skin worsens, so it stops one row beyond the true minimum."]'::jsonb, 0, 'Its best row reports 1.8471799468076697 against the searched 1.6363280590574483, which is the difference between the best design offered and the best design available.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 6, 'Given that the two routes disagree, which should carry the design decision, and what is the other good for?', '["Trust the grid, because every one of its rows is a real computed design.", "Trust whichever route reports the more negative pseudo-skin, since the two differ only by a rounding of the ninth half-length.", "Trust the continuous search, since it can stop between the rows, and keep the grid to show the shape of the trade.", "Trust the published constant over both, given that the two computed routes disagree with each other."]'::jsonb, 2, 'Skin differs little between the two answers because the minimum is flat, so the grid misleads about the exact location rather than about the shape.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 7, 'Multiplying half-length by propped width returns the same figure in every row of the sweep. What is that product standing for?', '["The fracture height, held at 30 m across the whole sweep.", "The fixed volume of proppant placed, which is what puts length and width into competition with each other.", "The created fracture volume before closure, which exceeds the propped volume by the ratio of created width to propped width.", "The dimensionless conductivity, which is proportional to the product of propped width and half-length."]'::jsonb, 1, 'Double the length and the width halves, and that constraint is the only reason the search has a minimum to find at all.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 8, 'Take the 30 m end of the sweep, where the pack is thick and the conductivity reaches 16.62461952126903. What has gone wrong there?', '["It falls outside the stated range of the skin correlation.", "It has ample reach but too little conductivity to bring the collected oil back to the well.", "It cannot carry its own inflow, because a pack that thick has its permeability cut by the closure stress acting over a short face.", "It carries far more than it is asked to carry, yet reaches just 30 m into a 1 mD formation, so it drains very little."]'::jsonb, 3, 'Its pseudo-skin of -4.852065115237415 is the worst but one in the table, and conductivity you cannot fill is money left in the hole.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 9, 'At 440 m the sweep reports a pseudo-skin of -4.59691654548207, the poorest in the table. Why does the far end of that fracture do so little?', '["Oil enters along the whole length and then meets a channel too thin to pass it, so the tip is largely decorative.", "The fracture no longer reaches the drainage radius of 300 m.", "The propped width of 0.0005152988864257336 m falls under the grain diameter of the proppant, so no pack forms out at the tip.", "Net pressure has dropped so far by 440 m that the fracture closes before any proppant arrives."]'::jsonb, 0, 'Effective wellbore radius falls to 10.711227534493757 m there, against a peak of 24.185315963132414 m at the 90 m row.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 10, 'That final row carries a dimensionless conductivity of 0.07728387174143661. What ought to be said about the pseudo-skin printed beside it?', '["Quoting it is fine, since the engine computed it from the same correlation.", "It lies above the correlation ceiling of 1000, so the skin is extrapolated.", "It sits under the correlation''s stated floor of 0.1, so the value prints but is no longer a reading you should quote.", "It should be dropped and replaced by the 340 m value, that being the last half-length still inside the correlation''s stated ground."]'::jsonb, 2, 'Being outside 0.1 to 1000 is something to state in the review rather than to work around quietly, because the printed figure looks identical either way.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 11, 'A completed job comes in with its dimensionless conductivity well under the optimum. Which way should the design move?', '["Towards more length, so the pack has more face to cover.", "Towards more conductivity or less length, since the pack cannot carry what a fracture that long collects.", "Towards more proppant in every instance, given that neither length nor width can move once the trade is fixed at a volume.", "Towards a lower closure stress, that being the one lever which raises retained pack permeability."]'::jsonb, 1, 'Above the optimum the remedies mirror, more length or less conductivity, because at fixed proppant the trade runs symmetrically both ways.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 12, 'How does the published 150 m job read against that diagnostic, and what is the correction which costs nothing?', '["Its conductivity of 0.6649847808507611 lies under 1.6, so it is transport limited; place the same proppant shorter.", "It sits above the optimum, so the fracture wants lengthening.", "It sits almost exactly at the optimum, so the right action is to leave the design as it stands and spend nothing.", "It is transport limited, and the only real fix is a stronger proppant that crushes less under the closure stress."]'::jsonb, 0, 'A damage factor of 0.5 is applied in that case, so half the pack permeability is thrown away before the well is ever opened, and the optimum is flat enough that the job still performs.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 13, 'Pseudo-skin is defined against one particular flow picture. Which picture, and what does it leave out?', '["Transient radial flow, leaving out the boundary dominated period.", "Steady linear flow into the fracture face, leaving out the radial convergence close to the wellbore.", "Pseudosteady depletion of a bounded circular area, leaving out any allowance for the pressure support an aquifer would supply.", "Steady single phase radial flow to a 300 m drainage radius, leaving out the early linear and bilinear period."]'::jsonb, 3, 'Effective wellbore radius means the radius an unfractured well in that same geometry would need to match the rate, so the optimum is a late time statement.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 14, 'Height containment is assumed identically at every half-length in the table. Why do the long rows strain it hardest?', '["Long fractures are pumped for longer, so the rock has more time to creep.", "Longer fractures call for a higher injection rate, and rate is the term which sets the bounding stress contrast.", "Net pressure climbs with length on the PKN model, and rising net pressure is just what drives height out of the interval.", "The pack is spread thinner at long half-lengths, and a thinner pack offers less resistance to vertical movement of fluid out of the zone."]'::jsonb, 2, 'The rise is from 2076588.0505800513 Pa at a 40 m half-length to 3436494.6050675157 Pa at 300 m, so the rows least entitled to a fixed height are exactly the long ones.'),
  ('stimulation', 'advanced', 'module', 'm05-the-unified-design-optimum', 15, 'Which design question does this optimum settle, and which does it stay silent on?', '["It settles both, since a productivity index is a proxy for revenue.", "It says how to spend proppant already bought, and nothing about whether buying it earns the money back.", "It answers the economic question directly, because pseudo-skin is converted into incremental production before the search is run.", "It fixes the proppant volume to buy, leaving the placement of that proppant to the pumping schedule."]'::jsonb, 1, 'No proppant cost, pumping cost, oil price, discount rate or decline enters the model, so where proppant is dear the money optimum can sit a long way off 1.6.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 1, 'A trainee hands in a worked chain whose pad fraction is identical to one minus efficiency. Which of the capstone checks has just failed, and what follows below it?', '["Nothing has failed, because the two forms agree whenever efficiency is low.", "The area check has failed, so the areal concentration is doubled and the propped width doubles with it.", "The pad fraction check has failed, so the pad runs long and every proppant figure beneath it comes out too small.", "The efficiency check has failed, and the remedy is to lift the end of job concentration until the placed mass recovers."]'::jsonb, 2, 'The two forms are only equal at zero efficiency, so any positive efficiency should open a visible gap between them.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 2, 'A reservoir engineer is handed a fracture pseudo-skin to drop straight into a model and asks whether it was measured. What should the stimulation engineer reply?', '["It was not measured. It is the end of a chain, and each link in that chain rests on a judgement somebody made.", "It is measured, since closure stress and pack permeability both come from the field record.", "It is measured in the sense that the correlation behind it was fitted to laboratory conductivity cells, so the value inherits their accuracy and needs no further comment.", "It is neither measured nor computed, being a convention the industry agreed for finite conductivity fractures."]'::jsonb, 0, 'The judgements sit in the leakoff coefficient, the pad fraction, the pack porosity, the stress dependent permeability and the damage factor.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 3, 'A design review shows a propped width sitting only just below the average created width for the same job. What ought the reviewer to suspect before believing the number?', '["That the proppant was unusually strong at this closure stress.", "That the fracture closed further than the PKN model allows, which lifts the propped width towards the created one.", "The pad fraction, because a short pad leaves a longer ramp and the extra slurry raises the propped width until it approaches the created width.", "An arithmetic slip, most likely a missing pack porosity or a placed mass that is too large for the area it covers."]'::jsonb, 3, 'On the published job the propped width is 0.0015115434001821517 m against an average created width of 0.004015981871358954 m.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 4, 'A candidate reports a placed mass equal to the final design concentration multiplied by the whole ramp volume. What step has been skipped?', '["The damage factor, which has to be applied to the mass before it is reported.", "The integration of the ramp. Concentration climbs from zero, so the job spends most of its ramp below the final value.", "The subtraction of the pad volume, since the pad also carries a share of the design concentration towards the end of its stage.", "The conversion from slurry volume to clean volume, which the blender record reports separately."]'::jsonb, 1, 'The engine divides by one plus the Nolte exponent, which is exactly what that integral of the power law contributes.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Two engineers on the same review disagree over whether the area under an areal concentration counts one wing or both. How can the argument be settled there and then?', '["Recompute the placed mass back out of the areal concentration and see whether it returns the mass that was pumped.", "Read the fracture height off the PKN model, which fixes the wing count.", "Compare the answer against the leakoff area used in the material balance, which counts the same faces in the same way and so must agree with it.", "Take the larger of the two answers, because a conservative areal concentration protects the design."]'::jsonb, 0, 'Both wings are counted once each, which is half the area the leakoff calculation works with, and the factor of two is silent if it is wrong.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 6, 'A marker notices that a submitted capstone matches the published golden case number for number all the way down. What does that tell the marker?', '["The candidate has passed, since matching the published case proves the chain was worked correctly.", "The candidate has rounded at every stage, because only rounding could reproduce a published figure exactly.", "The candidate has worked the published case rather than the conditions the capstone actually issued to them.", "The candidate has used the panel rather than working by hand, and the panel is seeded with the published inputs whenever a field is left blank in it."]'::jsonb, 2, 'The capstone runs its own conditions, so an exact match with the published figures is evidence of the wrong case rather than of a correct method.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 7, 'An engineer opens the capstone at the propped width step because an efficiency was already to hand from an earlier run. Why is that shortcut dangerous?', '["The steps must be attempted in order for the grading script to accept them.", "Efficiency is the most condition sensitive quantity in the tier, and a wrong one survives every later stage unnoticed.", "Efficiency is used only by the schedule, so importing it is safe, and the real risk is that the closure stress differs between the two runs instead.", "The earlier run would have used a different proppant, so its grain density is what actually invalidates the reuse."]'::jsonb, 1, 'An error introduced at the top arrives at the skin looking entirely plausible, which is why each stage carries its own check.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 8, 'A worked chain for a propped fracture finishes with a positive pseudo-skin. How should that result be read?', '["As a fracture too short to reach past the damaged zone.", "As a fracture whose dimensionless conductivity has fallen under the floor of the correlation''s stated validity band.", "As an ordinary outcome when the damage factor is severe, because a heavily damaged pack cannot return a negative skin however long the fracture is.", "As a signal of an error somewhere upstream in the chain rather than as a fracture that has failed to help the well."]'::jsonb, 3, 'The partner check is the effective wellbore radius, which must come out far above the drilled radius of 0.108 m on the published job.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 9, 'A reviewer finds that a colleague''s dimensionless conductivity is out by three orders of magnitude while every input looks sensible. Which conversion is the usual culprit?', '["The formation permeability, which has to be carried into the ratio in square metres using 9.869233e-16 m2 per mD.", "The closure stress, which is tabulated in thousands of psi rather than in pascals.", "The areal concentration, which is quoted in kilogrammes per square metre while the pack density is quoted per cubic metre.", "The propped width, which the catalogue reports in millimetres although the conductivity product expects it in metres and so shifts the answer by a thousand."]'::jsonb, 0, 'Catalogue permeabilities are quoted in darcy while formation permeability is quoted in millidarcy, and the two meet for the first time in this ratio.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 10, 'A colleague argues that the single conductivity figure carried by this tier flatters what the fracture will really deliver. Which physics is absent from the bookkeeping?', '["Non-Darcy flow, which lowers the effective permeability at high rates.", "Fluid loss to the formation, which this tier assumed away and which removes proppant along with the carrier fluid it leaves behind.", "Proppant transport. Grains settle, convect and bridge, so the pack is banked low and the tip sees little of the last stage.", "Closure creep, which keeps narrowing the pack for years after the job."]'::jsonb, 2, 'The step beyond is a transport model carrying a concentration field, which returns conductivity as a profile along the fracture rather than as one number.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 11, 'A team asks why they should trust an optimum half-length when the fracture may well grow out of zone. What limits the models used here, and where does the missing input come from?', '["Nothing limits them, since height growth cancels out of the optimum.", "PKN and KGD both hold height fixed, so the answer needs a stress profile against depth taken from a geomechanics log.", "The models allow height growth but not width growth, so the missing input is the rock stiffness measured on core rather than logged.", "The limit is the correlation''s validity band, and the input that resolves it is a longer proppant catalogue covering the deeper stresses the fracture reaches."]'::jsonb, 1, 'Pseudo three dimensional and planar three dimensional models solve height, length and width together instead of assuming one of them.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 12, 'A supervisor asks how a completed design should be described in a report when no minifrac or diagnostic injection has yet been pumped on the well. What is the honest wording?', '["As a hypothesis. Every number in it was forward modelled and none of it has been held against a job record.", "As provisional until the proppant catalogue has been checked against the supplier.", "As a validated design, because the engine''s own checks were all run and passed before it was issued to the field.", "As an estimate whose uncertainty is carried by the damage factor, which is the only input in the whole chain that was assumed rather than computed for the well."]'::jsonb, 0, 'A minifrac returns a real leakoff coefficient and a real closure pressure, which replaces two of the assumptions the chain rests on.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 13, 'During the main treatment an engineer watches the log-log slope of net pressure against time on the job record. What is that slope being read for?', '["The fluid efficiency, which the slope gives directly.", "The placed mass, since the slope tracks how much proppant has entered the fracture at any moment during the treatment.", "The pack permeability at the closure stress the fracture will eventually see once the pumps have come off.", "Which regime the fracture is in, whether contained extension, growth in height, or a screenout already under way."]'::jsonb, 3, 'Pressure matching is the discipline that closes the loop, replacing assumed leakoff and closure values with ones the well itself produced.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Two engineers argue for weeks about the right half-length for a well and get nowhere. What is that disagreement usually about underneath?', '["The choice of fracture model, PKN against KGD.", "The formation permeability, which neither of them can measure well enough to settle the optimum between them.", "The size of the job, which is an economic choice about proppant, horsepower, production and price rather than a physical one.", "The damage factor, since the two engineers will have assumed different values and the optimum half-length moves with it."]'::jsonb, 2, 'The physics optimum is applied after the size is settled, because it redistributes a proppant volume it does not choose.'),
  ('stimulation', 'advanced', 'module', 'm06-the-expert-reading', 15, 'A hiring manager asks a candidate what this Expert tier lets them claim they can do unaided. Which claim does the tier actually support?', '["Predicting the treating pressure a job will record at surface.", "Taking a pumped schedule through the pack it leaves and its conductivity, to the skin that follows, and saying what each link lost.", "Designing the proppant itself, since the tier covers grain density, pack porosity and the way permeability falls with closure stress.", "Choosing the size of the job, because the optimum in this tier fixes the proppant volume as well as the half-length it should be spread over."]'::jsonb, 1, 'The chain runs material balance, schedule, ramp, pack, conductivity and skin, and the tier''s habit is to read that chain rather than its final number.'),
  ('stimulation', 'advanced', 'final', null, 1, 'Where does an over-pumped pad show up later in the pack the well finally owns?', '["Less time is left to carry solid, so a smaller mass is placed and the propped width comes out thinner.", "The pack is unchanged, since the pad carries no proppant anyway.", "The pack is wider than planned, because the extra clean fluid opens more width for the grains to settle into before closure.", "The pack keeps its width but stops short of the tip, since the pad displaces slurry away from the far wing."]'::jsonb, 0, 'The created length is unaffected, which is why the job record looks normal while the propped length is short.'),
  ('stimulation', 'advanced', 'final', null, 2, 'Suppose a leakier fluid drops the efficiency to 0.054451800554703535. How much of the pump time is then left to carry solid?', '["A little under half of the pump time still remains for slurry.", "The pad and the ramp split the time evenly, because the exponent is bounded above by one half at low efficiency.", "The pad takes 0.8967201715127071 of the time, leaving barely a tenth of the job to place any proppant.", "About one twentieth of the time goes to pad, since the pad fraction follows the efficiency directly."]'::jsonb, 2, 'Placed mass is proportional to ramp time, so fluid selection is a proppant decision as much as a width decision.'),
  ('stimulation', 'advanced', 'final', null, 3, 'A field record shows the last blender stage arriving below the 800 kg/m3 design concentration. Is the schedule at fault?', '["Yes, the blender has failed to reach its final set point.", "No, every stage is sampled at its midpoint, so the last one lands just below the end of job value.", "Yes, the power law is concave, so a correctly executed schedule should overshoot the design concentration on its last stage.", "No, the ramp is cut short by one stage to guard against a screenout at the perforations."]'::jsonb, 1, 'Midpoint sampling is what keeps the staircase from running rich or lean against the curve it approximates.'),
  ('stimulation', 'advanced', 'final', null, 4, 'A modelling exercise sets the leakoff coefficient to zero. What schedule does Nolte''s algebra then prescribe?', '["Half the job as pad, with a linear ramp after it.", "A pad running almost the whole job, because with no leakoff there is nothing to keep the fracture open once the pumps stop.", "No pad, but a steeply concave ramp whose exponent climbs towards one.", "No pad at all and a flat ramp, because the exponent is zero when the efficiency reaches one."]'::jsonb, 3, 'Nothing leaks off, so the fracture volume equals the injected volume and width is available from the first minute.'),
  ('stimulation', 'advanced', 'final', null, 5, 'Doubling the end of job concentration on an otherwise unchanged treatment does what to the dimensionless conductivity?', '["It is unchanged, because concentration does not enter conductivity.", "It falls by half, because a richer slurry loses more fluid to leakoff and the fracture ends up shorter than the plan intended.", "It roughly doubles, since twice the mass gives twice the areal loading and twice the propped width.", "It rises fourfold, because the added mass lifts the pack permeability as well as the width."]'::jsonb, 2, 'Pack permeability is a property of the grains and the closure stress, so added mass moves width alone.'),
  ('stimulation', 'advanced', 'final', null, 6, 'A tight fluid on a low leakoff well returns an efficiency of 0.6326359683290029. How does its schedule differ from the published one?', '["Only 0.22501282514741658 of the time is pad, and the ramp reaches near its final value much earlier.", "The pad is longer and the ramp climbs more steeply.", "The pad is about the same, since the pad fraction is dominated by the injection rate rather than by the efficiency of the fluid.", "Roughly a third of the job is pad, because one minus the efficiency sets the split."]'::jsonb, 0, 'The exponent falls as efficiency rises, so a clean fluid spends less on pad and reaches concentration sooner.'),
  ('stimulation', 'advanced', 'final', null, 7, 'Take a design sitting at the optimum and pump the naive pad on it. Where does the conductivity diagnostic then read?', '["Still at the optimum, since the pad does not carry proppant.", "Above 1.6, because the extra pad opens a wider fracture and the same proppant then builds a thicker and more conductive pack.", "Below 0.1, so the reading falls outside the correlation and cannot be quoted at all.", "Below 1.6, because the shortened ramp places less mass, thinning the pack over the same half-length."]'::jsonb, 3, 'The created length is if anything longer, so the design also carries unpropped reach that contributes nothing.'),
  ('stimulation', 'advanced', 'final', null, 8, 'A spreadsheet spreads the placed mass over the same area the leakoff calculation used. What comes out of the pack stage?', '["The same answer, since both areas count the two wings.", "An areal concentration half the true value, so the propped width and the conductivity are halved as well.", "An areal concentration twice the true value, because the leakoff area counts one wall of one wing rather than both.", "A correct width but a conductivity out by two, since the error lands after the density division."]'::jsonb, 1, 'Leakoff crosses both walls of both wings, while the propped width is the single gap between the two walls.'),
  ('stimulation', 'advanced', 'final', null, 9, 'Suppose a service company demonstrates a perfectly broken fluid and the damage factor is lifted from 0.5 to 1. What happens to the reading against 1.6?', '["The retained permeability doubles, so the ratio doubles too and moves nearer 1.6 without reaching it.", "Nothing moves, since damage acts on width rather than permeability.", "The ratio passes above 1.6, so the design becomes length limited and the correct response is to lengthen the fracture.", "The ratio rises by roughly a third, which is the share of the pack the porosity accounts for."]'::jsonb, 0, 'A factor of one is a laboratory condition, so a claim of undamaged permeability is one you must be ready to defend.'),
  ('stimulation', 'advanced', 'final', null, 10, 'Leaving the pack porosity out of the bulk density travels how far down the chain?', '["It stops at the width, since conductivity uses the areal loading.", "It cancels out by the conductivity step, because the pack permeability already describes a void network of the same porosity.", "All the way, understating width, then conductivity, then the negative skin, and finally the effective radius.", "It overstates every downstream number, which is why such an error is caught quickly in review."]'::jsonb, 2, 'A pessimistic error survives review for years because nobody complains about a well that beat its forecast.'),
  ('stimulation', 'advanced', 'final', null, 11, 'A client wants more proppant in the ground without changing the fluid or the pump rate. Which lever remains?', '["The half-length, which sets how much mass the fracture holds.", "The end of job concentration, since ramp time follows the efficiency and the rate is already fixed.", "The number of blender stages, because each extra stage adds its own slurry volume on top of the ramp that was already planned.", "The pack porosity, which converts the placed mass into the width the fracture keeps."]'::jsonb, 1, 'Stages are equal in time and in volume, so changing their count reshapes the staircase without adding mass.'),
  ('stimulation', 'advanced', 'final', null, 12, 'The same treatment is re-planned at twice the half-length. Follow the areal concentration, the width and the ratio against 1.6.', '["Every one of the three halves, since the trade is linear.", "Loading and width halve while the dimensionless ratio holds, because the half-length cancels between the numerator and denominator.", "Loading halves but width holds, since the pack settles to the same thickness whatever the area.", "Loading and width both halve, conductivity halves, and the dimensionless ratio falls to a quarter."]'::jsonb, 3, 'Half-length enters twice, once by thinning the pack and once in the denominator of the ratio.'),
  ('stimulation', 'advanced', 'final', null, 13, 'A soft formation is on the programme and the same 0.5 damage factor is proposed. Which mechanism deserves the most scrutiny?', '["Gel residue, which depends only on the breaker schedule.", "Fines migration, because a soft rock crushes the proppant harder than a competent one at any given closure stress.", "Embedment, since the grains sink into weak walls and the pack loses width it was counted on having.", "Filter cake on the fracture face, which is the one mechanism a soft rock makes worse."]'::jsonb, 2, 'Embedment costs width rather than permeability, so it attacks the other half of the conductivity product.'),
  ('stimulation', 'advanced', 'final', null, 14, 'Somebody sets the pack porosity to zero, reasoning that it is the conservative choice. What follows?', '["The engine refuses the input, and the choice was not conservative anyway since it would overstate the width.", "The engine accepts it and returns a slightly narrower pack.", "The engine clamps the value at the bottom of its range and flags the result, in the way it clamps a closure stress outside the table.", "The width comes out larger by roughly a third, which is the conservative direction for a design."]'::jsonb, 0, 'Porosity must lie strictly between zero and one, since a porosity of one would make the width infinite.'),
  ('stimulation', 'advanced', 'final', null, 15, 'A design already at the optimum is moved to a deeper well where closure reaches the 8 kpsi row. What must change?', '["Nothing, since the optimum is a dimensionless target.", "The fracture should be lengthened, because a deeper well drains a larger area and the extra reach recovers the lost conductivity.", "Only the pad fraction, since closure stress enters the schedule through the material balance.", "Permeability falls to 70 darcy and the ratio drops below 1.6, so shorten the fracture or improve the grains."]'::jsonb, 3, 'The table runs from 250 darcy at 2 kpsi to 70 darcy at 8 kpsi, and beyond that the engine clamps rather than extrapolates.'),
  ('stimulation', 'advanced', 'final', null, 16, 'A vendor supports a deep candidate by quoting the 250 darcy catalogue figure. Which corrections must be applied first?', '["Convert the figure from darcy to millidarcy before use.", "Interpolate the table to the actual closure stress, then multiply by the damage factor the design will carry.", "Divide by the pack porosity and then by the propped width, since the catalogue is quoted per unit of areal loading.", "Only the damage factor, since the catalogue value already sits at the well''s closure."]'::jsonb, 1, 'At the published closure of 5.530572 kpsi the table interpolates to about 131.98 darcy before damage is applied.'),
  ('stimulation', 'advanced', 'final', null, 17, 'The identical pack is placed in a rock ten times more permeable than the published 1 mD. What does the skin routine do?', '["The ratio falls tenfold and lands under 0.1, so the skin still prints but carries a range warning.", "The routine throws, since the correlation refuses values under 0.1.", "The ratio is unaffected, because formation permeability appears in the conductivity and in the denominator alike.", "The ratio rises tenfold and approaches the upper limit of the stated band at 1000."]'::jsonb, 0, 'Only a non-positive conductivity or permeability, or a half-length inside the wellbore, will make the routine throw.'),
  ('stimulation', 'advanced', 'final', null, 18, 'Two designs share a proppant volume, one reaching a ratio of 16.62461952126903 and the other 1.8471799468076697. Which wins?', '["The first, because a more conductive channel always outproduces a longer one.", "Neither, because the two rows describe the same fracture read at different closure stresses and cannot be compared.", "The second, since its skin of -5.411369722473095 beats the shorter design by more than half a skin unit.", "The first, since it sits far above 1.6 and the optimum is a floor rather than a target."]'::jsonb, 2, 'A 30 m fracture is a fine pipe with nothing to collect, which is why very high ratios are a warning at fixed proppant.'),
  ('stimulation', 'advanced', 'final', null, 19, 'Changing to a fluid that leaks less lifts the efficiency. Trace that change through to the dimensionless conductivity.', '["The ratio is unchanged, since efficiency governs only the pad.", "A shorter pad leaves a longer ramp, so more mass, a thicker pack and a higher ratio at the same length.", "The ratio falls, because a fluid that leaks less builds a longer fracture and the added length thins the pack that fills it.", "The ratio rises through the pack permeability, which improves when less gel is left behind."]'::jsonb, 1, 'Efficiency enters the pack only through the ramp time, since the rate and the design concentration are unchanged.'),
  ('stimulation', 'advanced', 'final', null, 20, 'Which hurts the dimensionless ratio more, halving the damage factor or doubling the half-length at fixed mass?', '["Halving the damage factor, which removes half the pack outright.", "They cost the same, because both act once on the conductivity in the numerator and leave the denominator untouched.", "Doubling the length, but only by a factor of two, since width and length cancel in the ratio.", "Doubling the length, since it thins the pack and enlarges the denominator, costing a factor of four."]'::jsonb, 3, 'Halving the damage factor costs a factor of two, so length is the more expensive of the two moves.'),
  ('stimulation', 'advanced', 'final', null, 21, 'Ceramic proppant was chosen and still the published job sits under 1.6. Account for that.', '["The formation permeability of 1 mD is simply too high.", "The ceramic was the wrong choice, since a resin coated sand holds more permeability at this closure and would have reached the optimum.", "Closure removed roughly half the 250 darcy, damage halved the rest, and the design is 150 m long.", "The naive pad fraction was used, which is the usual reason a ratio falls short."]'::jsonb, 2, 'Ceramic pushes the collapse further down the stress axis rather than removing it, and the catalogue is planning data only.'),
  ('stimulation', 'advanced', 'final', null, 22, 'A colleague building a nodal model asks for one number to stand for the fracture. What do you hand over?', '["The effective wellbore radius, stated as valid for stabilised radial flow of a single phase only.", "The propped width, since it is the pack the well actually keeps.", "The fracture conductivity in millidarcy metres, because a nodal model reads the pack directly and forms its own skin.", "The dimensionless conductivity, which carries pack and formation together."]'::jsonb, 0, 'One radius substitutes for another and everything downstream in the model carries on unchanged.'),
  ('stimulation', 'advanced', 'final', null, 23, 'A build-up run soon after the treatment looks nothing like a 21.889652014700083 m borehole. Has the design failed?', '["Yes, the effective radius should be visible from the first hour.", "Yes, the pseudo-skin must be recomputed from the build-up, since the correlation was fitted to transient rather than stabilised data.", "No, but only because a week is too soon for the gel to have broken in the pack.", "No, the equivalence is a late-time statement, and the early data is linear and then bilinear instead."]'::jsonb, 3, 'Fracture diagnostics read the early data precisely because that is where the fracture rather than the equivalent hole shows itself.'),
  ('stimulation', 'advanced', 'final', null, 24, 'A redesign wins one further unit of negative pseudo-skin. What does that buy in equivalent hole size?', '["It adds one metre to the effective wellbore radius.", "The effective radius is multiplied again by the exponential, so there is no linear intuition to use.", "It raises the effective radius in proportion to the skin, so a move from five to six units gains about a fifth.", "Nothing, because the effective radius is capped by the drainage radius of 300 m."]'::jsonb, 1, 'The published skin of -5.3116380662677045 already turns a 0.108 m hole into 21.889652014700083 m.'),
  ('stimulation', 'advanced', 'final', null, 25, 'Two rows return f values of 0.7747563182826578 and 3.7154822332881525. What separates them?', '["The low value belongs to a generous pack, the high one to a starved pack below the stated 0.1 floor.", "The high value marks the better fracture, since f is the prize.", "They differ only in the wellbore radius used, because f takes the logarithm of the length ratio as its argument.", "The low value comes from a long fracture, since f falls as the half-length grows."]'::jsonb, 0, 'The 0.07728387174143661 row is printed with a range warning, so its f should be read as direction and nothing more.'),
  ('stimulation', 'advanced', 'final', null, 26, 'The carbonate acid job in this course reaches -1.287406553 while the fracture reaches -5.3116380662677045. Why the gulf?', '["Acid is applied to a smaller interval than a fracture.", "The two are measured against different wellbore radii, so the numbers are not on a common basis and should not be compared.", "Acid at best restores the rock it cleans, while the fracture changes the geometry of the flow path.", "Acid raises permeability and a fracture raises porosity, which counts for more."]'::jsonb, 2, 'A perfectly cleaned up damaged sandstone can only reach zero, so any large negative skin implies changed geometry.'),
  ('stimulation', 'advanced', 'final', null, 27, 'Set the published effective radius of 21.889652014700083 m against a drainage radius of 300 m. What has the fracture done?', '["It has removed radial flow from the problem completely.", "It has cut the radial squeeze from about three and a half decades to barely more than one.", "It has left the drainage geometry untouched, since the effective radius is only a bookkeeping device inside the skin term.", "It has doubled the drainage area the well can reach within the same reservoir."]'::jsonb, 1, 'The inflow equation prices scale logarithmically, which is where the production increase actually comes from.'),
  ('stimulation', 'advanced', 'final', null, 28, 'The well is opened the day after pumping and underperforms what the effective radius promised. Explain honestly.', '["The proppant has flowed back and the fracture has closed.", "The correlation was applied outside its stated range, which is the usual reason a fractured well disappoints on the first day.", "The damage factor of 0.5 was too generous and should have been set lower in design.", "The fluid is not broken, the pack is loaded with gel, and the design conductivity is not yet in place."]'::jsonb, 3, 'The equivalence assumes the pack has reached its retained permeability, which is a settled condition and not a flowback one.'),
  ('stimulation', 'advanced', 'final', null, 29, 'A reviewer will not take a design target on the authority of a paper. What can be shown from the engine alone?', '["The catalogue rows, which fix the target through the closure stress.", "The published constant printed straight from the engine source, which is the same authority simply written down in a second place.", "A search for the best pseudo-skin at fixed proppant, which lands on 1.6363280590574483 unaided.", "The discrete sweep, whose best row of 1.8471799468076697 confirms the target exactly."]'::jsonb, 2, 'The search never reads CFD_OPTIMUM, so agreement within a couple of per cent is an independent result.'),
  ('stimulation', 'advanced', 'final', null, 30, 'Somebody proposes refining the nine row sweep to ninety rows. What would that gain?', '["The best row would creep towards the searched answer, but a grid still returns only a row it was handed.", "Nothing, since the sweep is already continuous between its rows.", "It would move the optimum itself, because a denser grid changes the proppant volume each row has to spread over the face.", "It would replace the search entirely, since a fine enough grid is exact."]'::jsonb, 0, 'The nine row grid stops at 90 m because 90 m was on the list, not because the design is best there.'),
  ('stimulation', 'advanced', 'final', null, 31, 'Moving a 150 m design to 95.62290278496067 m is proposed at a review. How strong is the case?', '["Very strong, because the job is outside the correlation range as it stands.", "Weak, because a shorter fracture drains less rock and the pseudo-skin would worsen once the length term is recomputed.", "Very strong, since the effective radius would more than double on the same proppant.", "Directionally right but small, since the skin only improves to -5.4132436175894565 near a flat minimum."]'::jsonb, 3, 'The effective radius moves from 21.889652014700083 m to 24.230679198301456 m, which is real but modest.'),
  ('stimulation', 'advanced', 'final', null, 32, 'Funding is found for more proppant than the design assumed. Does the 1.6 target still govern?', '["No, the target moves upward as the proppant volume increases.", "It governs how to spend whatever volume is bought, but the size of the purchase is an economic question.", "Yes, and it also settles the volume, since the search returns the proppant purchase that maximises productivity.", "No, because with proppant no longer fixed the pseudo-skin has no minimum to find at any length."]'::jsonb, 1, 'More proppant is always better in this model, which is exactly why the model cannot choose the job size.'),
  ('stimulation', 'advanced', 'final', null, 33, 'Pay with only a weak stress contrast above it is to be fractured at the optimum. Which assumption is at risk?', '["Contained height, and the data that settles it is a stress profile from a geomechanics log.", "Single phase flow, which fails wherever the bounding shale is weak.", "Fixed proppant volume, because a fracture that grows in height needs a larger purchase to hold the same optimum ratio.", "Steady radial flow, since height growth keeps the well in a transient regime for longer."]'::jsonb, 0, 'Net pressure climbs with length on the PKN model, so the longest designs are the least entitled to a fixed height.'),
  ('stimulation', 'advanced', 'final', null, 34, 'One retained permeability is used from the wellbore to the tip. What does a real pack do instead?', '["It holds the catalogue value, since damage acts only near the well.", "It grows more permeable towards the tip, because the closure stress falls away from the wellbore and crushes fewer grains.", "Proppant settles and the tip never sees the last stage, so conductivity varies along the fracture.", "It behaves uniformly, which is why one damage factor is a sufficient description."]'::jsonb, 2, 'The damage factor of 0.5 is the whole allowance made for settling, banking and a starved tip.'),
  ('stimulation', 'advanced', 'final', null, 35, 'A well will be produced hard for six months and then handed on. Which part of the fracture''s worth escapes the pseudo-skin?', '["The conductivity, which the skin never sees directly.", "The linear and bilinear period, where the fracture is worth more than a steady comparison suggests.", "The height growth out of zone, which adds reach that the steady state calculation prices at zero throughout the life.", "Nothing important, because the correlation was fitted to the transient solution too."]'::jsonb, 1, 'The optimum is a late-time statement, so an early-life comparison understates every fractured candidate.'),
  ('stimulation', 'advanced', 'final', null, 36, 'Before a fracture skin enters a full field model, which judgements behind it should be laid out?', '["The wellbore radius and the drainage radius alone.", "Only the half-length and the proppant type, since everything else in the chain cancels by the time a skin is formed.", "The treating pressure record, which is the measurement the skin was fitted against.", "The leakoff coefficient, the pad form, the pack porosity, the stress table and the damage factor."]'::jsonb, 3, 'A skin is the end of a chain of judgements rather than a measurement, so each of them travels with it.'),
  ('stimulation', 'advanced', 'final', null, 37, 'A planar three-dimensional model is bought to replace the geometry step. Which link does it improve?', '["The pack, since it carries a concentration field through the fracture.", "The skin, because a three-dimensional model computes the pseudo-skin directly and no longer needs the fitted correlation.", "The geometry, solving height with length and width from a stress profile, leaving the pack and skin untouched.", "The calibration, since such a run is matched to the treating record by construction."]'::jsonb, 2, 'Its most important input is the stress profile against depth, which comes from a log rather than from the fracture model.'),
  ('stimulation', 'advanced', 'final', null, 38, 'What would a proppant transport model change about the conductivity this tier reports?', '["It would return a profile along the fracture, with a bank low down and a tip the last stage never reached.", "It would raise the number, since transport recovers what damage removed.", "It would leave conductivity alone and change only the schedule, because transport is a pumping question rather than a pack question.", "It would replace the damage factor with a measured value from the treating record."]'::jsonb, 0, 'This tier places proppant by bookkeeping, turning pumped mass into one uniform pack thinned by a single multiplier.'),
  ('stimulation', 'advanced', 'final', null, 39, 'A diagnostic injection is pumped ahead of the main job. Which assumed inputs stop being assumptions?', '["The pack porosity and the proppant grain density.", "The damage factor and the retained permeability, since the injection returns fluid that can be tested for unbroken gel.", "The fracture height and the formation permeability, which the injection resolves directly.", "The leakoff coefficient and the closure pressure, both of which the tier had to take on trust."]'::jsonb, 3, 'The log-log slope of net pressure during the main treatment then says which regime the fracture is actually in.'),
  ('stimulation', 'advanced', 'final', null, 40, 'Of everything fed into the chain, which single input moves the final skin furthest if it is misread?', '["The wellbore radius, which sits inside the logarithm.", "The fluid efficiency, because the pad, the ramp and every proppant number below it descend from that solve.", "The number of blender stages, since the staircase sets how much of the ramp is spent below the design concentration.", "The formation permeability, which enters only the denominator of the ratio."]'::jsonb, 1, 'Efficiency is the most condition-sensitive number in the tier, which is why the capstone solves it first and alone.'),
  ('stimulation', 'advanced', 'final', null, 41, 'One request asks for a comparison of stimulation options and another for an inflow relationship. Which figure goes where?', '["Pseudo-skin for the comparison, effective wellbore radius for the inflow relationship.", "Conductivity in both, since it is the only measured quantity.", "Effective radius for the comparison and pseudo-skin for the inflow relationship, since only a radius is common to acid and fracture work.", "Dimensionless conductivity for both, because it is the one figure independent of the wellbore."]'::jsonb, 0, 'Both are honest for a settled well, and neither belongs in a forecast of the first weeks of production.'),
  ('stimulation', 'advanced', 'final', null, 42, 'A junior asks why the tier labours over propped width when only a skin is wanted downstream. Answer them.', '["Width is needed for the pump schedule rather than for the skin.", "The skin is obtained independently of the width, so width is carried through the calculation only as a check on the placed mass.", "The skin descends from that width through conductivity, so its worth cannot be judged without the chain.", "Width matters only where the fracture might screen out during placement."]'::jsonb, 2, 'Read the chain rather than the last number, because each link is a judgement somebody made.');
